const captures=await (await fetch('captures.json')).json(),$=s=>document.querySelector(s);
let selected=0,compare=false;
function figure(c,label){const f=document.createElement('figure'),img=document.createElement('img'),cap=document.createElement('figcaption');img.src=c.image;img.alt=c.title+'. '+c.caption;cap.textContent=label;f.append(img,cap);return f;}
function show(i){selected=Math.max(0,Math.min(captures.length-1,i));const c=captures[selected];$('#stage').replaceChildren(figure(c,c.latest?'Now · Your production screenshot':`${selected+1} · ${c.title}`));if(compare&&!c.latest)$('#stage').append(figure(captures.at(-1),'Now · Laurel Orchard Ranch'));$('#title').textContent=c.title;$('#caption').textContent=c.caption;$('#position').textContent=`Milestone ${selected+1} / ${captures.length}`;$('#source').textContent=`Source: ${c.source} · File archive time: ${c.archiveTime}.`;$('#prev').disabled=selected===0;$('#next').disabled=selected===captures.length-1;for(const [j,b]of [...$('#timeline').children].entries())b.setAttribute('aria-current',String(j===selected));history.replaceState(null,'','#'+c.id);}
for(const [i,c]of captures.entries()){const b=document.createElement('button'),img=document.createElement('img'),label=document.createElement('span'),small=document.createElement('small');img.src=c.image;img.alt='';img.loading='lazy';small.textContent=c.latest?'NOW':String(i+1).padStart(2,'0');label.append(small,document.createTextNode(c.title));b.append(img,label);b.onclick=()=>show(i);$('#timeline').append(b);}
$('#prev').onclick=()=>show(selected-1);$('#next').onclick=()=>show(selected+1);$('#compare').onclick=()=>{compare=!compare;$('#compare').setAttribute('aria-pressed',String(compare));show(selected);};$('#about').onclick=()=>$('#info').showModal();$('#close').onclick=()=>$('#info').close();document.addEventListener('keydown',e=>{if($('#info').open||e.target.tagName==='BUTTON')return;if(e.key==='ArrowRight')show(selected+1);if(e.key==='ArrowLeft')show(selected-1);});show(Math.max(0,captures.findIndex(c=>c.id===location.hash.slice(1))));

const moveSettings=()=>{const b=document.querySelector("#app-settings-toggle");if(!b)return false;document.querySelector("header").append(b);return true;};if(!moveSettings()){const observer=new MutationObserver(()=>{if(moveSettings())observer.disconnect();});observer.observe(document.body,{childList:true});}
